#!/usr/bin/env python3
# Frozen train826-only package; no competition submission.
import base64,json,zlib,subprocess,sys
from pathlib import Path
subprocess.check_call([sys.executable,'-m','pip','install','--quiet','transformers==4.57.1','safetensors==0.6.2','huggingface-hub==0.36.0','soundfile==0.13.1'])
p=Path('/kaggle/working/f_wavlm_source');p.mkdir(parents=True,exist_ok=True)
for n,c in json.loads(zlib.decompress(base64.b64decode(''))).items():(p/n).write_text(c)
subprocess.check_call([sys.executable,str(p/'extract.py')])
